#include "thinkercad/spibus.hpp"
#include <cmath>
#include <limits>
#include <stdexcept>
#include <algorithm>
namespace thinkercad {
namespace {
bool powered(const CircuitPart& part,const ModuleDefinition& model,const CircuitState& state){const auto v=state.voltage.find({part.id,model.power}),g=state.voltage.find({part.id,model.ground});if(v==state.voltage.end()||g==state.voltage.end()||!v->second||!g->second||*v->second-*g->second<model.minVoltage||*v->second-*g->second>model.maxVoltage)return false;if(model.implementation=="mfrc522"){const auto reset=state.voltage.find({part.id,"RST"});if(reset==state.voltage.end()||!reset->second||*reset->second-*g->second<.7*(*v->second-*g->second))return false;}return true;}
bool selected(const CircuitPart& part,const ModuleDefinition& model,const CircuitState& state){const auto cs=state.voltage.find({part.id,"CS"}),g=state.voltage.find({part.id,model.ground});return cs!=state.voltage.end()&&g!=state.voltage.end()&&cs->second&&g->second&&*cs->second-*g->second>=-.1&&*cs->second-*g->second<.5;}
std::uint8_t reverse(std::uint8_t value){std::uint8_t out=0;for(int bit=0;bit<8;++bit){out=(out<<1)|(value&1);value>>=1;}return out;}
}
void SpiBus::refreshSelects(const CircuitDocument& doc,const CircuitState& state){devices_.synchronizePower(doc,state);for(const auto& part:doc.parts())if(part.kind==PartKind::Module){const auto& model=ModuleRegistry::get(part.model);if(model.bus=="spi")devices_.select(part,powered(part,model,state)&&selected(part,model,state));}}
SpiBus::Reply SpiBus::transfer(const CircuitDocument& doc,const CircuitState& state,const std::string& board,int sck,int miso,int mosi,unsigned clock,int mode,bool lsb,std::uint8_t value,Microseconds now){
    Reply result;if(!clock||clock>80000000||mode<0||mode>3)throw std::invalid_argument("Invalid SPI settings");const auto profile=BoardProfile::get(doc.part(board).model);for(int pin:{sck,miso,mosi})if(profile.pinNumber(profile.pinName(pin))<0)throw std::invalid_argument("Invalid SPI bus pin");refreshSelects(doc,state);std::vector<const CircuitPart*> matches;
    for(const auto& part:doc.parts())if(part.kind==PartKind::Module){const auto& model=ModuleRegistry::get(part.model);if(model.bus!="spi"||!powered(part,model,state)||!selected(part,model,state))continue;if(!doc.connected({part.id,model.ground},{board,"GND"})||!doc.connected({part.id,"SCK"},{board,profile.pinName(sck)})||!doc.connected({part.id,"MISO"},{board,profile.pinName(miso)})||!doc.connected({part.id,"MOSI"},{board,profile.pinName(mosi)}))continue;matches.push_back(&part);}
    if(matches.empty())return result;if(matches.size()!=1){result.status=Status::Collision;return result;}const auto& part=*matches.front();result.id=part.id;const auto& model=ModuleRegistry::get(part.model);if(clock>model.maxClock){result.status=Status::Clock;return result;}if(mode!=model.spiMode&&!(model.implementation=="bme280"&&mode==3)){result.status=Status::Mode;return result;}
    if(model.implementation=="mcp3008"){const auto ref=state.voltage.find({part.id,"VREF"}),ground=state.voltage.find({part.id,model.ground});if(ref==state.voltage.end()||ground==state.voltage.end()||!ref->second||!ground->second||*ref->second-*ground->second<=0||*ref->second-*ground->second>5.5){result.status=Status::Reference;return result;}std::array<double,8> inputs;for(int i=0;i<8;++i){const auto at=state.voltage.find({part.id,"CH"+std::to_string(i)});inputs[i]=at!=state.voltage.end()&&at->second?*at->second-*ground->second:std::numeric_limits<double>::quiet_NaN();}devices_.setAnalog(part.id,inputs,*ref->second-*ground->second);}
    if(model.implementation=="mfrc522"){std::vector<std::uint8_t> uid;int matches=0;const int defaults[]={4,161,178,195,212,229,246};for(const auto& card:doc.parts())if(card.kind==PartKind::NfcTestCard&&card.pressed&&parameter(card,"channel",0)==parameter(part,"channel",0)&&std::hypot(card.x-part.x,card.y-part.y)<=900){++matches;uid.clear();for(int i=0;i<int(parameter(card,"uidLength",7));++i)uid.push_back(std::uint8_t(parameter(card,"uid"+std::to_string(i),defaults[i])));}if(matches!=1)uid.clear();devices_.setCard(part.id,std::move(uid));}
    result.value=devices_.spi(part,lsb?reverse(value):value,now);if(lsb)result.value=reverse(result.value);result.status=Status::Ok;return result;
}
const char* SpiBus::description(Status value){switch(value){case Status::Ok:return "OK";case Status::Unselected:return "No selected powered device on this SPI bus";case Status::Collision:return "SPI collision: multiple chip-selects asserted";case Status::Clock:return "SPI clock exceeds device rating";case Status::Mode:return "SPI mode is incompatible with device";case Status::Reference:return "ADC reference is missing or invalid";}return "SPI error";}
}
